const { expectedRates, cellDoneChance } = require("./model.js");
// Q1: where is expected exactly 0 with realistic settings?
for (const r of [4, 6, 7]) {
  const zero = expectedRates(100, r, 0.005).filter((g) => g.casesPerPerson === 0).map((g) => g.start + "-" + g.end);
  console.log(`r=${r}: groups with expected exactly 0:`, zero.join(", ") || "none");
}
// Q2a: Poisson tail vs bell-curve tail. "yellow or worse" = z >= 2, "red" = z > 3.
function poissonAtLeast(k, m) { let term = Math.exp(-m), below = 0; for (let j = 0; j < k; j++) { below += term; term *= m / (j + 1); } return 1 - below; }
const bellYellow = 0.02275, bellRed = 0.00135;
console.log("\nexpected | chance z>=2 (bell: 2.3%) | chance z>3 (bell: 0.13%) | lowest z possible");
for (const m of [0.5, 1, 2, 5, 10, 20, 50]) {
  const sd = Math.sqrt(m);
  const kY = Math.ceil(m + 2 * sd), kR = Math.floor(m + 3 * sd) + 1;
  const pY = poissonAtLeast(kY, m), pR = poissonAtLeast(kR, m);
  console.log(String(m).padStart(8), "|", (100 * pY).toFixed(2).padStart(6) + "%", `(${(pY / bellYellow).toFixed(1)}x)`.padEnd(8), "        |", (100 * pR).toFixed(3).padStart(7) + "%", `(${(pR / bellRed).toFixed(1)}x)`.padEnd(8), "      |", (-m / sd).toFixed(2));
}
// Q2b: expected cases per group in the default run (M = 20,000)
console.log("\ndefault run, M=20000 N=100 r=4 p=0.005: expected cases per group");
console.log(expectedRates(100, 4, 0.005).map((g) => `${g.start}-${g.end}: ${(20000 * g.casesPerPerson).toFixed(1)}`).join("  "));
'

