  const use = g.filter((x) => x.start >= fromAge && x.start <= toStart);
  return fitLine(use.map((x) => Math.log(x.start + 2)), use.map((x) => Math.log(rateOf(x)))).slope;
}
const pyRate = (x) => x.rate, oldRate = (x) => x.casesPerPerson / (5 * S(x.start));
