svg.push(`<line x1="${lx}" y1="${ly + 44}" x2="${lx + 24}" y2="${ly + 44}" stroke="${INK}" stroke-width="2"/><text x="${lx + 30}" y="${ly + 48}" font-size="12" fill="${INK}">exact rate from the formula (no randomness), slope ${ef.slope.toFixed(2)}</text>`);

