}

// ---------------------------------------------------------------------------
// Figure 8: why the exact slope is 2.84, not 3. Start from the simple formula and
// add one real-world detail at a time; refit the slope (groups 25-29 .. 80-84,
// middle ages start + 2.5, logLogFit from model.js) after each step.
// ---------------------------------------------------------------------------
{
  const { logLogFit, expectedRates } = require("./model.js");
  const N = 100, r = 4, p = 0.005;
  const starts = [];
  for (let g = 25; g <= 80; g += 5) starts.push(g);
  const mids = starts.map((g) => g + 2.5);
  const slopeOf = (rates) => logLogFit(mids, rates).slope;
  const fact = (n) => (n <= 1 ? 1 : n * fact(n - 1));
  const perGroup = (f) => starts.map((g) => { let s = 0; for (let a = g + 1; a <= g + 5; a++) s += f(a); return s / 5; });
  const Fsimple = (t) => (N * p ** r * t ** r) / fact(r); // cumulative of the simple formula
  const steps = [
    ["Simple formula at the middle age", slopeOf(mids.map((t) => (N * p ** r * t ** (r - 1)) / fact(r - 1)))],
    ["+ average over each 5-year group", slopeOf(starts.map((g) => (Fsimple(g + 5) - Fsimple(g)) / 5))],
    ["+ whole years (count the ways)", slopeOf(perGroup((a) => N * choose(a - 1, r - 1) * p ** r))],
    ["+ every other year must be a miss", slopeOf(perGroup((a) => N * choose(a - 1, r - 1) * p ** r * (1 - p) ** (a - r)))],
    ["+ 100 cells, people drop out (full model)", slopeOf(expectedRates(N, r, p).filter((g) => g.start >= 25).map((g) => g.rate))],
  ];
  const W = 760, H = 400, left = 300, right = 80, top = 90, rowH = 50;
  const x0 = 2.7, x1 = 3.2;
  const xp = (v) => left + ((v - x0) / (x1 - x0)) * (W - left - right);
  const s = svgStart(W, H, "Why the exact slope is 2.84, not 3", "Start from the simple formula, add one detail at a time, refit the slope. r = 4, N = 100, p = 0.005.");
  for (const v of [2.7, 2.8, 2.9, 3.0, 3.1, 3.2]) {
    s.push(`<line x1="${xp(v)}" y1="${top - 10}" x2="${xp(v)}" y2="${top + steps.length * rowH}" stroke="${v === 3 ? "#b5b4ae" : GRID}" ${v === 3 ? 'stroke-dasharray="4 3"' : ""}/>`);
    s.push(`<text x="${xp(v)}" y="${top + steps.length * rowH + 18}" font-size="12" fill="${MUTED}" text-anchor="middle">${v.toFixed(1)}</text>`);
  }
  s.push(`<text x="${(left + W - right) / 2}" y="${top + steps.length * rowH + 40}" font-size="13" fill="${MUTED}" text-anchor="middle">slope of the log-log line (dashed: r − 1 = 3)</text>`);
  console.log("\nFigure 8: slope after each step");
  steps.forEach(([label, v], i) => {
    const y = top + i * rowH + rowH / 2;
    const prev = i === 0 ? null : steps[i - 1][1];
    const big = prev !== null && Math.abs(v - prev) > 0.05;
    s.push(`<text x="${left - 14}" y="${y + 4}" font-size="13" fill="${INK}" text-anchor="end"${big ? ' font-weight="600"' : ""}>${label}</text>`);
    if (prev !== null) s.push(`<line x1="${xp(prev)}" y1="${y - rowH + 6}" x2="${xp(v)}" y2="${y - 6}" stroke="#b5b4ae" stroke-width="1.5"/>`);
    s.push(`<circle cx="${xp(v)}" cy="${y}" r="6" fill="${big ? ORANGE : BLUE}"/>`);
    const change = prev === null ? "" : `  (${v - prev >= 0 ? "+" : "−"}${Math.abs(v - prev).toFixed(3)})`;
    s.push(`<text x="${xp(v) + 12}" y="${y + 4}" font-size="12" fill="${INK}">${v.toFixed(3)}${change}</text>`);
    console.log(`  ${label.padEnd(44)} ${v.toFixed(4)}${change}`);
  });
  s.push("</svg>");
  fs.writeFileSync(path.join(OUT, "8-why-2.84.svg"), s.join("\n"));
  console.log("  miss factor 0.995^(years): age 30 " + (0.995 ** 26).toFixed(3) + ", age 60 " + (0.995 ** 56).toFixed(3) + ", age 80 " + (0.995 ** 76).toFixed(3));
}

