      s.push(`<text x="${xp(a) + (f === simple ? -8 : 8)}" y="${yp(f(a)) + (f === simple ? -10 : 18)}" font-size="12" fill="${color}" text-anchor="${f === simple ? "end" : "start"}">${f(a).toFixed(1)}</text>`);
