cd /Users/cameronkani/02-120_Project/web && node -e '
const m=require("./model.js");
for (const [M,N] of [[20000,100],[5000,400],[2000,1000],[200,10000]]){
  const ex=m.expectedRates(N,4,0.005);
  const e25=M*ex[5].casesPerPerson, e80=M*ex[16].casesPerPerson;
  const life=ex.reduce((a,g)=>a+g.casesPerPerson,0);
  const exSlope=m.runReport(M,N,4,0.005,1).exactFit.slope;
  let t=Date.now(); const slopes=[];
  for(let s=1;s<=6;s++){const r=m.runReport(M,N,4,0.005,s); if(r.simulatedFit) slopes.push(r.simulatedFit.slope);}
  const ms=(Date.now()-t)/6, mean=slopes.reduce((a,b)=>a+b)/slopes.length, sd=Math.sqrt(slopes.reduce((a,b)=>a+(b-mean)**2,0)/(slopes.length-1));
  console.log(`M ${M} N ${N}: ${ms.toFixed(0)} ms/run, lifetime risk ${(100*life).toFixed(1)}%, expected cases 25-29 ${e25.toFixed(1)}, 80-84 ${e80.toFixed(0)}, exact slope ${exSlope.toFixed(3)}, sim slopes mean ${mean.toFixed(2)} sd ${sd.toFixed(2)}`);
}'

